/**
 * ============================================================
 * AERCOM CRM v2
 * Reportes Module
 * Migrado tal cual desde index.html (Sprint 13)
 * ============================================================
 *
 * Responsabilidad: "Reporte de Vencimientos" — documento HTML
 * standalone (KPIs, 2 gráficos Chart.js, tablas de equipos
 * vencidos/próximos 30 días/próximos 60 días) que se abre en una
 * ventana nueva (`window.open` + `document.write`) pensado para
 * imprimir o guardar como PDF (Ctrl+P). Es un documento HTML
 * completo embebido en un template string — su propio `<style>`
 * y `<script>` (con la carga de Chart.js vía CDN e instanciación
 * de los 2 gráficos) corren en el `document` de esa ventana nueva,
 * no en el de la app — por eso la referencia a Chart.js dentro del
 * template no es una segunda carga de la librería en la página
 * principal.
 *
 * Dependencias externas (definidas en index.html / js/utils.js,
 * sin mover — no son responsabilidad de este módulo):
 *   D, toast(), clientName(), daysDiff(), fmtDate(), addDays(),
 *   _esc() (js/utils.js — PR-014.1, hardening XSS)
 *
 * `_LOGO_RPT` (logo en base64 embebido en el header del reporte)
 * es una constante de uso exclusivo de este reporte — se migra
 * junto con la función.
 *
 * No se toca Excel, Google Drive ni CSV Import — quedan pendientes
 * de extracción aparte, según el alcance de este PR.
 */

const _LOGO_RPT = "data:image/png;base64,";

function generarReporteVencimientos(){
  const hoy = new Date(); hoy.setHours(0,0,0,0);
  const hoySt = hoy.toISOString().split('T')[0];

  function nextDates(eq){
    const cli = D.clientes.find(c=>c.id===eq.clienteId);
    const FD  = {'Semanal':7,'Quincenal':15,'Mensual':30,'Bimestral':60,'Trimestral':90,'Semestral':180,'Anual':365};
    return {
      nextPrev: eq.proximoPreventivo || null,
      nextBat:  eq.proximoBateria    || (eq.ultimoBateria ? addDays(eq.ultimoBateria,730)  : null),
      nextRef:  eq.proximoAceite     || (eq.ultimoAceite  ? addDays(eq.ultimoAceite,730)   : null),
      nextVis:  eq.proximaVisita     || (eq.ultimaVisita && FD[cli?.frecuenciaVisita||''] ? addDays(eq.ultimaVisita,FD[cli?.frecuenciaVisita||'']) : null)
    };
  }

  const vencidos=[], prox30=[], prox60=[], alDia=[];
  D.equipos.forEach(eq=>{
    const nd = nextDates(eq);
    const dates = [nd.nextPrev,nd.nextBat,nd.nextRef,nd.nextVis].filter(Boolean);
    if(!dates.length){ alDia.push({eq,...nd,minDiff:9999}); return; }
    const minDiff = Math.min(...dates.map(d=>daysDiff(d)));
    const obj = {eq,...nd,minDiff};
    if(minDiff<0)        vencidos.push(obj);
    else if(minDiff<=30) prox30.push(obj);
    else if(minDiff<=60) prox60.push(obj);
    else                 alDia.push(obj);
  });
  vencidos.sort((a,b)=>a.minDiff-b.minDiff);
  prox30.sort((a,b)=>a.minDiff-b.minDiff);
  prox60.sort((a,b)=>a.minDiff-b.minDiff);

  const tipoCount={};
  D.equipos.forEach(eq=>{ tipoCount[eq.tipo]=(tipoCount[eq.tipo]||0)+1; });

  const fecha = hoy.toLocaleDateString('es-AR',{weekday:'long',year:'numeric',month:'long',day:'numeric'});
  const fechaCorta = `${hoy.getDate().toString().padStart(2,'0')}/${(hoy.getMonth()+1).toString().padStart(2,'0')}/${hoy.getFullYear()}`;

  function tableRows(list){
    if(!list.length) return '<tr><td colspan="6" style="text-align:center;color:#9b9a96;padding:16px;font-style:italic">Sin equipos en esta categoría</td></tr>';
    return list.map(item=>{
      const cn = clientName(item.eq.clienteId);
      const d = item.minDiff;
      const dLabel = d===9999?'—': d<0
        ? `<span style="color:#c73030;font-weight:700">${Math.abs(d)}d vencido</span>`
        : `<span style="color:#c4600a;font-weight:700">en ${d}d</span>`;
      const fd = v=>v?fmtDate(v):'—';
      return `<tr style="border-bottom:1px solid #f0efeb">
        <td style="padding:8px 10px;font-size:12px;font-weight:600;color:#1a1916">${_esc(item.eq.id)}</td>
        <td style="padding:8px 10px;font-size:12px;color:#706f6b">${_esc(cn)}</td>
        <td style="padding:8px 10px;font-size:11px;color:#9b9a96">${item.eq.tipo}</td>
        <td style="padding:8px 10px;font-size:11.5px">${fd(item.nextPrev)}</td>
        <td style="padding:8px 10px;font-size:11.5px">${fd(item.nextBat)}</td>
        <td style="padding:8px 10px;text-align:center">${dLabel}</td>
      </tr>`;
    }).join('');
  }

  const tLabels = JSON.stringify(Object.keys(tipoCount));
  const tData   = JSON.stringify(Object.values(tipoCount));

  const html = `<!DOCTYPE html>
<html lang="es"><head><meta charset="UTF-8">
<title>Reporte de Vencimientos — Aercom SA</title>
<script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.js"><\/script>
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:'Segoe UI',Arial,sans-serif;background:#f8f8f7;color:#1a1916}
.page{max-width:980px;margin:0 auto;background:#fff;box-shadow:0 4px 32px rgba(0,0,0,.1)}
.rpt-header{background:linear-gradient(135deg,#1a1916 0%,#2c2a26 100%);color:#fff;padding:28px 40px;display:flex;align-items:center;justify-content:space-between}
.rpt-header img{height:36px;object-fit:contain}
.rpt-header-title{font-size:19px;font-weight:700;letter-spacing:-.3px;text-align:right}
.rpt-header-sub{font-size:11.5px;color:rgba(255,255,255,.55);margin-top:3px;text-align:right}
.rpt-band{background:linear-gradient(90deg,#1d6fa4,#2d8fd4);height:4px}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:#e8e6e1;border-bottom:1px solid #e8e6e1}
.kpi{background:#fff;padding:20px 24px}
.kpi-val{font-size:34px;font-weight:700;line-height:1;letter-spacing:-1.5px}
.kpi-lbl{font-size:10.5px;color:#9b9a96;margin-top:5px;text-transform:uppercase;letter-spacing:.5px;font-weight:600}
.cr{color:#c73030}.cw{color:#c4600a}.ci{color:#1d6fa4}.co{color:#0a7c5c}
.charts{display:grid;grid-template-columns:1fr 1fr;gap:0;border-bottom:1px solid #e8e6e1}
.chart-card{padding:24px 32px;border-right:1px solid #e8e6e1}
.chart-card:last-child{border-right:none}
.chart-title{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:#9b9a96;margin-bottom:14px}
.chart-wrap{position:relative;height:190px}
.sec{padding:24px 40px;border-bottom:1px solid #f0efeb}
.sec-title{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.6px;color:#1d6fa4;margin-bottom:14px;display:flex;align-items:center;gap:8px}
.sec-title::after{content:'';flex:1;height:1px;background:#e8e6e1}
.tbl{width:100%;border-collapse:collapse}
.tbl th{background:#f8f8f7;padding:8px 10px;text-align:left;font-size:10px;font-weight:700;color:#9b9a96;text-transform:uppercase;letter-spacing:.4px;border-bottom:2px solid #e8e6e1}
.tbl tr:hover td{background:#f8f8f7}
.br{background:#fdf0f0;color:#c73030;padding:2px 8px;border-radius:4px;font-size:10.5px;font-weight:700;display:inline-flex;align-items:center;gap:4px}
.bw{background:#fef3e2;color:#c4600a;padding:2px 8px;border-radius:4px;font-size:10.5px;font-weight:700;display:inline-flex;align-items:center;gap:4px}
.bo{background:#ebf7f2;color:#0a7c5c;padding:2px 8px;border-radius:4px;font-size:10.5px;font-weight:700;display:inline-flex;align-items:center;gap:4px}
.footer{background:#f8f8f7;padding:16px 40px;display:flex;justify-content:space-between;align-items:center;border-top:1px solid #e8e6e1}
.footer-txt{font-size:10.5px;color:#9b9a96}
@media print{body{background:#fff}.page{box-shadow:none;max-width:100%}}

/* ═══════════════════════════════════════════════════════════
   AERCOM POLISH — correcciones visuales finales
═══════════════════════════════════════════════════════════ */

/* Kanban — headers con color por estado, coherentes */
.k-col { border-radius: var(--r-md); overflow: hidden; }
.k-col-head { padding: 11px 14px; border-bottom: 1px solid var(--border); }
.k-col:has([data-estado="Solicitud"])      .k-col-head { background:#f5f5f3; color:#6b6b67; border-top:3px solid #9b9a96; }
.k-col:has([data-estado="Cotizar"])        .k-col-head { background:#e8f4fd; color:#1260a8; border-top:3px solid #1d6fa4; }
.k-col:has([data-estado="Enviar"])         .k-col-head { background:#dbeafe; color:#1d4ed8; border-top:3px solid #2563eb; }
.k-col:has([data-estado="En seguimiento"]) .k-col-head { background:#fef3e2; color:#b85e0a; border-top:3px solid #c4600a; }
.k-col:has([data-estado="Aprobada"])       .k-col-head { background:#ebf7f2; color:#0a7c5c; border-top:3px solid #0a7c5c; }
.k-col:has([data-estado="A facturar"])     .k-col-head { background:#fef3e2; color:#c4600a; border-top:3px solid #c4600a; }
.k-col:has([data-estado="Facturada"])      .k-col-head { background:#f3f0ff; color:#6d40c4; border-top:3px solid #6d40c4; }
.k-col:has([data-estado="Ejecutada"])      .k-col-head { background:#e2faf6; color:#0d7a6b; border-top:3px solid #0d7a6b; }
.k-col:has([data-estado="Rechazada"])      .k-col-head { background:#fdf0f0; color:#c73030; border-top:3px solid #c73030; }

/* Kanban cards — acento izquierdo coherente, sin overlap con border-top */
.k-card { border-radius: var(--r-md); overflow: visible; }
.k-card-accent { border-radius: 4px 0 0 4px; }

/* Ficha modal — borde superior azul limpio */
.ficha-modal { border-top: 3px solid var(--accent) !important; border-radius: var(--r-lg) !important; }
.ficha-head { border-top: none !important; border-radius: 0 !important; }

/* Modal editar cliente — asegurar scroll correcto */
#modal-overlay .modal { overflow-y: auto; }
.modal-body { overflow-y: visible; }

/* Stat cards del dashboard — borde top más visible */
.stat-card { border-top-width: 3px !important; }

/* Badges — consistencia de tamaño mínimo */
.badge { min-height: 20px; line-height: 1.2; }

/* Tabla — header border más fuerte */
th { border-bottom: 2px solid var(--border-strong) !important; }

/* Scrollbar más delgada y discreta */
::-webkit-scrollbar { width: 5px; height: 5px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--border-strong); border-radius: 99px; }
::-webkit-scrollbar-thumb:hover { background: var(--t3); }

/* Sidebar nav activo — acento izquierdo bien alineado */
.nav-item { position: relative; }
.nav-item.active::before {
  content: '';
  position: absolute;
  left: -12px;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 60%;
  background: var(--accent);
  border-radius: 0 3px 3px 0;
}



</style></head><body>
<div class="page">
  <div class="rpt-header">
    <img src="${_LOGO_RPT}" alt="Aercom SA">
    <div>
      <div class="rpt-header-title">Reporte de Vencimientos</div>
      <div class="rpt-header-sub">${fecha}</div>
    </div>
  </div>
  <div class="rpt-band"></div>

  <div class="kpis">
    <div class="kpi"><div class="kpi-val cr">${vencidos.length}</div><div class="kpi-lbl">Equipos vencidos</div></div>
    <div class="kpi"><div class="kpi-val cw">${prox30.length}</div><div class="kpi-lbl">Vencen en 30 días</div></div>
    <div class="kpi"><div class="kpi-val ci">${prox60.length}</div><div class="kpi-lbl">Vencen en 60 días</div></div>
    <div class="kpi"><div class="kpi-val co">${alDia.length}</div><div class="kpi-lbl">Al día</div></div>
  </div>

  <div class="charts">
    <div class="chart-card">
      <div class="chart-title">Estado de mantenimiento</div>
      <div class="chart-wrap"><canvas id="c1"></canvas></div>
    </div>
    <div class="chart-card">
      <div class="chart-title">Equipos por tipo</div>
      <div class="chart-wrap"><canvas id="c2"></canvas></div>
    </div>
  </div>

  <div class="sec">
    <div class="sec-title"><span class="br">⚠ Vencidos (${vencidos.length})</span></div>
    <table class="tbl"><thead><tr>
      <th>Equipo</th><th>Cliente</th><th>Tipo</th><th>Próx. Preventivo</th><th>Próx. Batería</th><th style="text-align:center">Estado</th>
    </tr></thead><tbody>${tableRows(vencidos)}</tbody></table>
  </div>

  <div class="sec">
    <div class="sec-title"><span class="bw">⏰ Próximos 30 días (${prox30.length})</span></div>
    <table class="tbl"><thead><tr>
      <th>Equipo</th><th>Cliente</th><th>Tipo</th><th>Próx. Preventivo</th><th>Próx. Batería</th><th style="text-align:center">Días restantes</th>
    </tr></thead><tbody>${tableRows(prox30)}</tbody></table>
  </div>

  <div class="sec">
    <div class="sec-title"><span class="bo">📅 Entre 31 y 60 días (${prox60.length})</span></div>
    <table class="tbl"><thead><tr>
      <th>Equipo</th><th>Cliente</th><th>Tipo</th><th>Próx. Preventivo</th><th>Próx. Batería</th><th style="text-align:center">Días restantes</th>
    </tr></thead><tbody>${tableRows(prox60)}</tbody></table>
  </div>

  <div class="footer">
    <span class="footer-txt">Aercom SA — Mantenimiento Industrial · aercom.com.ar</span>
    <span class="footer-txt">Generado: ${fechaCorta}</span>
  </div>
</div>
<script>
new Chart(document.getElementById('c1'),{type:'doughnut',data:{labels:['Vencidos','Próx.30d','Próx.60d','Al día'],datasets:[{data:[${vencidos.length},${prox30.length},${prox60.length},${alDia.length}],backgroundColor:['#c73030','#f59e0b','#1d6fa4','#0a7c5c'],borderWidth:0,hoverOffset:4}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'right',labels:{font:{size:11},boxWidth:12,padding:8}}}}});
new Chart(document.getElementById('c2'),{type:'bar',data:{labels:${tLabels},datasets:[{data:${tData},backgroundColor:['#1d6fa4','#0a7c5c','#c4600a','#6d40c4','#c73030'],borderRadius:5,borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{ticks:{font:{size:10}},grid:{display:false}},y:{ticks:{font:{size:10},precision:0},grid:{color:'#f0efeb'}}}}});
<\/script></body></html>`;

  const win = window.open('','_blank');
  if(!win){ toast('⚠ El navegador bloqueó la ventana del reporte — habilitá las ventanas emergentes para este sitio'); return; }
  win.document.write(html);
  win.document.close();
  win.focus();
  toast('✓ Reporte generado — Ctrl+P para imprimir o guardar como PDF');
}
